from pathlib import Path
from PIL import Image
import json,html,shutil
ROOT=Path(__file__).resolve().parents[1]
def main():
 m=json.loads((ROOT/'manifest.json').read_text());palette='palette' in ROOT.name
 if palette:
  old=ROOT.parent/'v01';refs={'approved-plumber.png':old/'native/CH4-B2-01-v01.png','approved-eddie.png':old/'native/CH4-B2-02-v01.png','approved-restroom-background.png':old/'native/CH4-B2-03-v01.png','approved-attendant.png':old/'references/approved-attendant.png','approved-presenter.png':old/'references/approved-presenter.png','approved-conductor.png':ROOT.parent/'b2-02-v01/references/approved-conductor.png','approved-groundkeeper.png':ROOT.parent/'b2-02-v01/references/approved-groundkeeper.png','foreman-style-original.png':ROOT.parent/'b2-02-v01/originals/CH4-B2-10-original.png'}
  (ROOT/'references').mkdir(exist_ok=True)
  for n,p in refs.items():
   shutil.copyfile(p,ROOT/'references'/n)
   if 'style-original' not in n:
    im=Image.open(p);im.resize((im.width*4,im.height*4),Image.Resampling.NEAREST).save(ROOT/'previews'/(Path(n).stem+'-4x.png'))
  title='B2-01 plumber portraits - compact palette v02';summary='Two NEW UNSELECTED palette alternatives. Approved v01 images remain registered and unchanged. Their character designs/poses guide the new stepped-ramp illustrations; geometry/alpha are not claimed pixel-identical after reillustration. Coherent64-tone final NPC ramps match the reduced-tone Chapter1/2 direction; detail is carried by features, hands, hair, seams and folds rather than gradients or grain.';comparison='plumbers-v01-v02';extras=[('Approved v01 plumber','references/approved-plumber.png','previews/approved-plumber-4x.png'),('Approved v01 Eddie','references/approved-eddie.png','previews/approved-eddie-4x.png')]
  for a in m['assets']:extras.append((a['title']+' on frozen approved background','previews/'+a['id']+'-composite.png','previews/'+a['id']+'-composite-4x.png'))
  notes='The approved background, receipt Focus A and master-isolator Focus A are unchanged. Eddie still holds the readable LOT14 receipt. The two internal quantization-only diagnostics are retained as diagnostics, not final review candidates. Source-derived reillustration originals, exact prompts and final palette recipe are preserved.'
 else:
  title='B2-02 - Loading dock and service arrivals v01';summary='Six NEW UNSELECTED candidates: four main scenes, one transparent detailed foreman portrait and one matching empty conversation background. All are disclosed source-derived production exports. Main-scene NPCs remain simpler and properly scaled; the detailed foreman uses the compact Chapter1/2-style stepped palette. No invented story nodes or engine integration.';comparison='B2-02-all';extras=[('Foreman over matching dock background','previews/foreman-composite.png','previews/foreman-composite-4x.png')]
  notes='The canonical seven-node group covers loading lane, service alley, loading dock, service stairs and the annoyed salvage foreman. The truck/staircase, sofa/trolley, chandelier hoist/padded container, two piano workers plus foreman, cake trolley and side gate follow their source nodes. The dialogue background contains no NPC. The side-gate view shows ordinary park vegetation only, no future-chapter hazard or bathroom sign. Internal staging corrections preserve all other reduced pixels before the recorded native finish.'
 def card(label,one,four,note='',id_=''):
  im=Image.open(ROOT/one);w,h=im.size
  return f'<article id="{id_}"><h2>{html.escape(label)}</h2><p>{note}</p><div class="controls"><button data-scale="1">Native 1x</button><button data-scale="4">Exact 4x</button><a href="{one}">PNG</a> · <a href="{four}">4x PNG</a></div><div class="strip"><div class="checker"><img class="art" src="{one}" data-one="{one}" data-four="{four}" data-w="{w}" data-h="{h}" width="{w}" height="{h}" alt="{html.escape(label)}"></div></div></article>'
 cards=[]
 for a in m['assets']:
  n=f"<strong>UNSELECTED</strong> · source-derived · <code>{a['key']}</code><br>Nodes: "+', '.join(a['nodeIds'])+f"<br>SHA256 <code>{a['native']['sha256']}</code>"
  cards.append(card(a['title'],a['native']['file'],a['preview4x']['file'],n,a['id']))
 for title_,one,four in extras:cards.append(card(title_,one,four,'Composite or approved reference, not another candidate.'))
 for n,label in [('approved-attendant','Approved Pavilion attendant'),('approved-presenter','Approved Pavilion presenter'),('approved-groundkeeper','Approved Chapter2 Groundskeeper -61 opaque colors'),('approved-conductor','Approved Chapter2 Conductor -50 opaque colors')]+([]if palette else [('approved-lobby','Approved Chapter4 lobby'),('approved-tower','Approved Chapter2 Control Tower'),('approved-pavilion-exterior','Approved Chapter3 exterior')]):cards.append(card(label,'references/'+n+'.png','previews/'+n+'-4x.png','Actual approved style/lighting/material benchmark; exact bytes preserved.'))
 head='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#182824;color:#eddfc5;font:16px/1.55 system-ui}main{max-width:1320px;margin:auto;padding:24px}a{color:#bfe4ce}h1{font-size:29px}h2{font-size:21px}article,section{border:1px solid #57695b;background:#22362f;padding:18px;margin:22px 0;min-width:0}.controls{display:flex;flex-wrap:wrap;gap:10px;align-items:center}button{font:inherit;padding:8px 14px;background:#405b49;color:#f7ead5;border:1px solid #90a38b;cursor:pointer}.strip{overflow:auto;max-width:100%;padding:10px;background:#11231d;margin-top:14px}.checker{width:max-content;background:repeating-conic-gradient(#42574d 0% 25%,#33483d 0% 50%) 0 0/16px 16px}img.art{display:block;max-width:none;image-rendering:pixelated;image-rendering:crisp-edges}code{font-size:12px;overflow-wrap:anywhere}nav{display:flex;flex-wrap:wrap;gap:16px}@media(max-width:600px){main{padding:10px}article,section{padding:10px}h1{font-size:23px}}</style>'''
 canonical='https://github.com/InterstellarHarvest/CYOA-storyboard/blob/fde5708e0043972feeae0309e8a1d1836e756dae/docs/128_CH4_B201_APPROVAL_COMPLETION_20261122.md'
 nav=f'<nav><a href="manifest.json">Manifest/hashes</a><a href="README.md">Production notes</a><a href="evidence/validation.json">QA</a><a href="evidence/generation-receipts.json">Generation provenance</a><a href="comparisons/{comparison}-native.png">Native comparison PNG</a><a href="comparisons/{comparison}-4x.png">Exact4x comparison PNG</a></nav>'
 intro='<main><header><h1>'+html.escape(title)+'</h1><p><strong>UNSELECTED - pending Nate</strong></p><p>'+summary+'</p></header>'+nav+'<section><h2>Review notes</h2><p>'+notes+'</p><p>Judge the actual native artwork and exact4x views against approved references. No CSS scaling or smooth interpolation is used. A compact color count is not visual approval.</p><p>B2-01 v01 is APPROVED and SELECTED unchanged. <a href="'+canonical+'">Canonical approval, exact hashes, paths and gameplay handoff</a>. These newer candidates are separate. <a href="'+('../b2-02-v01/README.md' if palette else '../v02-npc-palette/README.md')+'">'+('New loading-dock six-asset group' if palette else 'Requested plumber palette alternatives')+'</a>.</p></section>'
 script='''<script>document.querySelectorAll('button[data-scale]').forEach(b=>b.addEventListener('click',()=>{const i=b.closest('article').querySelector('img'),s=Number(b.dataset.scale);i.src=s===4?i.dataset.four:i.dataset.one;i.width=Number(i.dataset.w)*s;i.height=Number(i.dataset.h)*s;}));</script></main></html>'''
 (ROOT/'index.html').write_text(head+'<title>'+title+'</title>'+intro+''.join(cards)+script)
 readme=f'# {title}\n\n**UNSELECTED**. {summary}\n\n{notes}\n\n[Native/exact4x gallery](index.html), [manifest and exact hashes](manifest.json), [comparison PNG](comparisons/{comparison}-native.png), [4x comparison](comparisons/{comparison}-4x.png).\n\nThe built-in image_gen.imagegen tool generated the original illustrations; every source, exact prompt, generation receipt and input benchmark is preserved. Source-derived quality-first workflow: '+('new stepped-ramp source -> nearest564x278 -> binary alpha cleanup -> compact64-tone no-dither fit, then composites on the exact frozen approved background.' if palette else 'new composed environment sources -> controlled native transfer/finish; foreman -> nearest564x278, binary cutout and compact64-tone no-dither fit. Main scenes314x206, opaque background564x278, foreground564x278 transparent.')+' Never claim independent native-grid authorship. The64-tone NPC target is calibrated to actual Chapter2 references (50/61); environment colors are not forced under the same cap. No mathematical gradients or new anatomical shading are synthesized. Native/4x artistic comparisons matter more than counts.\n\nApproved v01/B1 images are never reprocessed or overwritten. New palette alternatives do not replace an owner selection automatically. Canonical registration is on main at fde5708e0043972feeae0309e8a1d1836e756dae (PR21); runtime assetPath remains null until separate verified game integration, per docs105/127/128. No narrative/gameplay/workflow changes.\n\nReproduce with the recorded Pillow version:\n\n```sh\nPYTHONDONTWRITEBYTECODE=1 python3 source/prepare.py\nPYTHONDONTWRITEBYTECODE=1 python3 source/package.py\nPYTHONDONTWRITEBYTECODE=1 python3 source/validate.py\n```\n\nOriginals/prompts: [generation receipts](evidence/generation-receipts.json); final derivation: '+('[palette treatment](evidence/palette-treatment.json).' if palette else '[derivation](evidence/derivation.json).')+' Source/qa-gallery.cjs exercises every native/exact4x control in Chromium/Firefox. Public file verification compares every published byte to the local package, with its output outside the commit.\n'
 (ROOT/'README.md').write_text(readme)
if __name__=='__main__':main()
